<script lang="ts">
	import { onMount } from 'svelte';
	import { systemHealth, type SystemHealthTelemetry } from './api';
	import { PageHeader, MetricCard } from './ui';
	import { uiText as t } from './i18n';
	let data=$state<SystemHealthTelemetry|null>(null),loading=$state(true),error=$state('');
	async function load(){loading=true;error='';try{data=await systemHealth();}catch(cause){error=cause instanceof Error?cause.message:t('Data tidak dapat dimuat.');}finally{loading=false;}}
	onMount(load);
</script>
<svelte:head><title>{t('Storage & Sistem')} · PasPapan</title></svelte:head>
<main class="workspace-page system-page" id="main-content" tabindex="-1"><PageHeader title={t('Storage & Sistem')} description={t('Konfigurasi layanan aktif dan kesehatan koneksi.')} backHref="/admin/dashboard">{#snippet actions()}<button class="quiet" disabled={loading} onclick={load}>{t('Segarkan')}</button>{/snippet}</PageHeader>{#if error}<p role="alert">{error}</p>{/if}{#if loading}<p role="status">{t('Memuat…')}</p>{:else if data}<section class="metrics"><MetricCard label={t('Berkas')} value={data.tenant.stored_files_count}/><MetricCard label={t('Sesi aktif')} value={data.tenant.active_sessions_count}/><MetricCard label={t('Audit Trail')} value={data.tenant.audit_events_count}/><MetricCard label="Database" value={data.postgres.database_size_pretty}/></section><div class="status-grid"><section class="panel"><h2>Object storage</h2><dl><div><dt>Driver</dt><dd>{data.storage.driver}</dd></div><div><dt>Bucket</dt><dd>{data.storage.bucket}</dd></div><div><dt>Region</dt><dd>{data.storage.region}</dd></div></dl><p class="muted">{t('Konfigurasi layanan dikelola pada environment deployment.')}</p></section><section class="panel"><h2>{t('Pengiriman email')}</h2><dl><div><dt>Driver</dt><dd>{data.mailer?.driver??'—'}</dd></div><div><dt>{t('Pengirim')}</dt><dd>{data.mailer?.from_address??'—'}</dd></div></dl></section><section class="panel"><h2>PostgreSQL {data.postgres.server_version}</h2><dl><div><dt>{t('Koneksi aktif')}</dt><dd>{data.postgres.activity.active_queries}/{data.postgres.max_connections}</dd></div><div><dt>Cache hit</dt><dd>{data.postgres.database_stats.cache_hit_ratio_pct}%</dd></div><div><dt>Deadlocks</dt><dd>{data.postgres.database_stats.deadlocks}</dd></div><div><dt>Pool</dt><dd>{data.sqlx_pool.active}/{data.sqlx_pool.size}</dd></div></dl></section></div>{/if}</main>
<style>
	.system-page{display:grid;gap:12px;align-content:start}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.status-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:12px}.panel{padding:16px;border-radius:var(--radius);min-width:0}h2{font-size:15px;margin:0 0 12px}dl{margin:0}dl>div{display:flex;justify-content:space-between;gap:12px;padding:8px 0;font-size:12px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere;text-align:right}.muted{font-size:11px;color:var(--muted)}@media(max-width:480px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
